editorial:
## Method and reasoning
View each direction as a forward scan by reversing the indexing for previous queries. In a doubled array, scan right-to-left for the nearest qualifying position. Pop values that are equal or on the wrong side of the comparison. For a position in the first copy accept the top only if its distance is less than n.

## Walk through the sample
In [3,1,4,2], scanning right from the final 2 wraps immediately to 3, a greater value at position 1. From the global minimum 1 there is no strictly smaller value, even after a full circuit.

## Complexity
Four passes take O(n), storing O(n) answers and giving O(1) per query.

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (auto &x : a)
        cin >> x;
    array<vector<int>, 4> answers;
    for (int type = 0; type < 4; ++type) {
        auto index = [&](int i) { return type < 2 ? i % n : n - 1 - i % n; };
        answers[type].resize(n);
        vector<int> stack;
        for (int i = 2 * n - 1; i >= 0; --i) {
            int x = a[index(i)];
            while (!stack.empty()) {
                int y = a[index(stack.back())];
                if (type % 2 == 0 ? y > x : y < x)
                    break;
                stack.pop_back();
            }
            if (i < n && !stack.empty() && stack.back() - i < n)
                answers[type][index(i)] = stack.back() - i;
            stack.push_back(i);
        }
    }
    while (q--) {
        int t, i;
        cin >> t >> i;
        cout << answers[t - 1][i - 1] << '\n';
    }
}
